                for i,d in enumerate(order):
                    if d in running: T[d]=T[lead]+min(i*0.55,6.0)+rng.normal(0,0.1)
            if lap==1 or lap==restart_lap:
                order=[d for d in sorted(running,key=lambda x:T[x])]
            else:
                arr=[d for d in order if d in running]; neworder=[]
                for i,d in enumerate(arr):
                    if i==0 or len(neworder)==0: neworder.append(d); continue
                    ahead=neworder[-1]
                    if T[d] < T[ahead]-80:
                        neworder.insert(len(neworder)-1,d); continue
                    if T[d] < T[ahead]+HOLD_GAP:
                        adv=(pace[ahead]+damaged.get(ahead,0))-(pace[d]+damaged.get(d,0))
                        if pitted[d]>pitted[ahead]: adv+=0.25
