    tot=[sum(res[d]['pos'][k] for d in DRIVERS) for k in range(22)]
    print("pos totals:",[round(t,3) for t in tot])
    err=(sum((res[d]['pos'][0]-MKT[d])**2 for d in MKT))**0.5
    print("RMSE vs mkt P1:",round(err,4))

